/**
 * Remove metacaracteres RQL (`* ( ) , \`) do input do usuário para evitar
 * quebra/manipulação da expressão montada no client.
 */
export function sanitizeCrmRqlLiteral(value: string): string {
  return value.replace(/[\\*(),]/g, '').trim();
}

