'use client';

import { useEffect, useMemo, useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { AlertTriangle, Calendar, CheckSquare, Layout, Plus, User } from 'lucide-react';
import { cn } from '@/lib/utils';
import {
    getProcessoVinculadoByIdQuery,
    getPostPurchaseByIdQuery,
} from '@/hooks/queries/post-purchase';
import { QueryKeys } from '@/constants/query-keys';
import { Tenants } from '@/enums/tenants.enum';
import { getTenantFromUrl } from '@/utils/getHostFromUrl';
import { getInitials } from '@/functions/formaters/getInitials';
import dateFormater from '@/functions/formaters/dateFormater';
import { Checkbox } from '@/components/ui/checkbox';
import { TruncatedText } from '@/components/ui/truncated-text';
import { COLORS } from '@/design-system';
import { useCrmUiStore } from '@/app/uniflow/crm/store/use-crm-ui-store';
import { sanitizeCrmRqlLiteral, useCrmBoard } from '@/app/uniflow/crm/hooks/use-crm-board';
import {
    applyOptimisticTaskStatus,
    restoreCrmTaskRelatedQueries,
    snapshotCrmTaskRelatedQueries,
} from '@/app/uniflow/crm/hooks/crm-task-cache';
import { invalidateUniflowCrmTaskDomain } from '@/app/uniflow/crm/hooks';
import { updateCrmTaskStatus } from '@/app/uniflow/crm/services';
import type { CrmBoardStreamItem, CrmTask, CrmUser, TaskStatus } from '@/app/uniflow/crm/types';
import type { CrmUserMini, ProcessoTarefaResumo } from '@/interfaces/IProcessoVinculado';
import { CreateTarefaModal } from './CreateTarefaModal';
import {
    INCLUDE_ARCHIVED_TASKS_LABEL,
    PRIORIDADE_BADGE_CLASSES,
    PRIORIDADE_LABELS,
    STATUS_BADGE_CLASSES,
    STATUS_BADGE_FALLBACK_CLASSES,
    STATUS_LABELS,
    TASKS_TAB_ARCHIVED_BOARD_PAGE_SIZE,
    TASKS_TAB_EMPTY_MIN_HEIGHT_PX,
    type TaskOwner,
} from './tarefa-constants';

export type { TaskOwner };

interface TasksTabProps {
    owner: TaskOwner;
    /** Layout compacto da coluna sticky (fora das tabs do main). */
    variant?: 'default' | 'rail';
}

function mapCrmUserToMini(user: CrmUser | null | undefined): CrmUserMini | null {
    if (!user) return null;
    return {
        id: user.id,
        username: user.username,
        email: user.email ?? '',
        nome: user.nome,
        avatarUrl: user.avatarUrl ?? null,
        sectorId: user.sectorId ?? null,
        teamId: user.teamId ?? null,
        cargo: '',
    };
}

function mapCrmTaskToResumo(task: CrmTask, fallbackMarcoId: string | null): ProcessoTarefaResumo {
    return {
        id: task.id,
        resumo: task.resumo,
        status: task.status,
        prioridade: task.prioridade,
        prazo_fatal: task.prazo_fatal ?? null,
        data_inicio: task.data_inicio ?? null,
        data_alerta: task.data_alerta ?? null,
        marcoId: task.marcoId ?? fallbackMarcoId,
        responsavel: mapCrmUserToMini(task.responsavel_detail),
        criado_por: mapCrmUserToMini(task.criado_por),
        created_at: task.created_at,
    };
}

function extractTasksFromBoard(
    items: CrmBoardStreamItem[],
    marcoId: string,
): ProcessoTarefaResumo[] {
    const byId = new Map<string, ProcessoTarefaResumo>();

    for (const item of items) {
        if (item.type === 'milestone' && item.id === marcoId) {
            for (const task of item.tasks) {
                byId.set(task.id, mapCrmTaskToResumo(task, marcoId));
            }
            continue;
        }
        if (item.type === 'task' && item.marcoId === marcoId) {
            byId.set(item.id, mapCrmTaskToResumo(item, marcoId));
        }
    }

    return Array.from(byId.values());
}

export function TasksTab({ owner, variant = 'default' }: TasksTabProps) {
    const isRail = variant === 'rail';
    const isFromDasi = getTenantFromUrl() === Tenants.DASI;
    const isProcesso = owner.kind === 'processo';

    const [isCreateOpen, setIsCreateOpen] = useState(false);
    const [includeArchivedTasks, setIncludeArchivedTasks] = useState(false);
    const openTaskPanel = useCrmUiStore((state) => state.openTaskPanel);
    const openMarcoPanel = useCrmUiStore((state) => state.openMarcoPanel);

    const queryClient = useQueryClient();

    const processoQuery = useQuery(getProcessoVinculadoByIdQuery(isProcesso ? owner.id : null));
    const posQuery = useQuery(getPostPurchaseByIdQuery(isProcesso ? null : owner.id));

    const { data, isLoading, isFetching, isError, refetch } = isProcesso ? processoQuery : posQuery;

    const toggleTarefaStatus = useMutation({
        mutationFn: ({ id, nextStatus }: { id: string; nextStatus: TaskStatus }) =>
            updateCrmTaskStatus(id, nextStatus),
        // Mesmo patch otimista do toggle do CRM (use-crm-task-mutations.ts): garante que o
        // painel do marco (que lê o cache de tarefas do CRM) reflita a mudança na hora,
        // sem depender do timing do invalidate/refetch abaixo.
        onMutate: async ({ id, nextStatus }) => {
            await queryClient.cancelQueries({ queryKey: [QueryKeys.uniflowCrm.tasks] });
            const snapshot = snapshotCrmTaskRelatedQueries();
            applyOptimisticTaskStatus(id, nextStatus);
            return { snapshot };
        },
        onError: (_error, _vars, context) => {
            if (context?.snapshot) restoreCrmTaskRelatedQueries(context.snapshot);
        },
        // invalidateUniflowCrmTaskDomain já cobre processos/pós-aquisição (ver invalidate.ts).
        onSettled: () => {
            void invalidateUniflowCrmTaskDomain();
        },
    });

    const handleToggleTarefaDone = (tarefa: ProcessoTarefaResumo) => {
        const nextStatus: TaskStatus = tarefa.status === 'CONCLUIDO' ? 'NAO_INICIADA' : 'CONCLUIDO';
        toggleTarefaStatus.mutate({ id: tarefa.id, nextStatus });
    };

    const detailTarefas = useMemo(() => data?.tarefas ?? [], [data?.tarefas]);
    const marcoIndisponivel = Boolean(data?.tarefasMarcoIndisponivel);
    // O detalhe do Pós-Aquisição/Processo já vem com o marco resolvido pelo backend
    // (todo registro tem um) — não depende mais de existir alguma tarefa criada.
    const marcoId = data?.marcoId ?? null;
    const canOpenCrmPanel = !isFromDasi && !marcoIndisponivel;
    const canFetchArchived = Boolean(marcoId) && !marcoIndisponivel;

    const archivedBoardQuery = sanitizeCrmRqlLiteral(marcoId ?? '');
    const boardQuery = useCrmBoard(
        {
            page: 1,
            pageSize: TASKS_TAB_ARCHIVED_BOARD_PAGE_SIZE,
            includeArchived: true,
            query: archivedBoardQuery ? `eq(milestone_id,${archivedBoardQuery})` : undefined,
